#include <stack>
#include <deque>

// Default stack declaration
std::stack<int> default_stack;

// Functionally equivalent to:
// std::stack<int, std::deque<int>> default_stack_explicit;

// Deque's design ensures push/pop are always O(1) 
// and memory is released efficiently upon pop().

for (int i = 0; i < 1000; ++i) {
    default_stack.push(i);
}
for (int i = 0; i < 500; ++i) {
    default_stack.pop(); // Memory segments are likely freed here
}
